INSERT INTO users (id, email, password_hash, name, phone, avatar_url, role, status, bio, created_at) VALUES
('user-traveler-01', 'traveler@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Nguyễn Văn Đức', '0912 345 678', 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=256&q=80', 'traveler', 'ACTIVE', 'Người yêu thích khám phá vẻ đẹp ẩm thực và kiến trúc các thành phố Việt Nam.', '2024-01-15T08:00:00Z'),
('user-host-01', 'host@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Trần Minh Quân', '0988 123 456', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=256&q=80', 'host', 'ACTIVE', 'Chủ nhà tận tâm tại RoomFinder. Đam mê văn hóa bản địa và kiến trúc tối giản.', '2021-03-10T10:00:00Z'),
('user-admin-01', 'admin@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Quản Trị Viên RoomFinder', '0900 000 000', 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?auto=format&fit=crop&w=256&q=80', 'admin', 'ACTIVE', 'Tài khoản quản trị hệ thống RoomFinder toàn quốc.', '2020-01-01T00:00:00Z'),
('user-host-02', 'thuha.nguyen@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Nguyễn Thu Hà', '0977 234 567', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=300&q=80', 'host', 'ACTIVE', 'Chào mừng bạn đến với căn hộ phong cách Scandinavian kết hợp Á Đông của mình. Yêu thích ẩm thực và luôn sẵn sàng hướng dẫn địa điểm ăn uống ngon.', '2021-06-01T08:00:00Z'),
('user-host-03', 'baongoc.le@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Lê Bảo Ngọc', '0912 345 678', 'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=300&q=80', 'host', 'ACTIVE', 'Host tận tâm tại Đà Nẵng và Hội An. Sẵn sàng đồng hành giúp bạn có kỳ nghỉ biển tuyệt vời và thư giãn nhất.', '2021-06-01T08:00:00Z'),
('user-host-04', 'ducanh.hoang@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Hoàng Đức Anh', '0903 456 789', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=300&q=80', 'host', 'ACTIVE', 'Kiến trúc sư trẻ yêu thích việc biến những không gian nhỏ thành nơi lưu trú tràn ngập ánh sáng tự nhiên và cây xanh.', '2021-06-01T08:00:00Z'),
('user-host-05', 'maiphuong.vu@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Vũ Mai Phương', '0934 567 890', 'https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=300&q=80', 'host', 'ACTIVE', 'Quản lý chuỗi căn hộ boutique tại trung tâm Quận 1 và Hoàn Kiếm. Tiêu chí hàng đầu là sự sạch sẽ, an toàn và dịch vụ chuyên nghiệp.', '2021-06-01T08:00:00Z'),
('user-host-06', 'tuankiet.dang@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Đặng Tuấn Kiệt', '0945 678 901', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=300&q=80', 'host', 'ACTIVE', 'Người Sài Gòn chính gốc, rất vui được đón tiếp du khách bốn phương trải nghiệm sự sôi động và lòng hiếu khách của thành phố.', '2021-06-01T08:00:00Z'),
('user-host-07', 'khanhlinh.bui@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Bùi Khánh Linh', '0967 890 123', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=300&q=80', 'host', 'ACTIVE', 'Đam mê nhiếp ảnh và du lịch bụi. Mỗi căn phòng đều được chăm chút cẩn thận từng chi tiết trang trí để bạn có những góc ảnh đẹp nhất.', '2021-06-01T08:00:00Z'),
('user-host-08', 'hoanglong.pham@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Phạm Hoàng Long', '0989 012 345', 'https://images.unsplash.com/photo-1492562080023-ab3db95bfbce?auto=format&fit=crop&w=300&q=80', 'host', 'ACTIVE', 'Chủ sở hữu các căn hộ condotel cao cấp ven biển Sơn Trà và trung tâm Tây Hồ. Hệ thống tự nhận phòng thông minh 24/7.', '2021-06-01T08:00:00Z'),
('user-host-09', 'thuychi.duong@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Dương Thùy Chi', '0976 112 233', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=300&q=80', 'host', 'ACTIVE', 'Yêu thiên nhiên và không gian sống xanh. Căn hộ có ban công nhiều hoa lá và góc ngắm hoàng hôn cực chill.', '2021-06-01T08:00:00Z'),
('user-host-10', 'quochuy.ngo@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Ngô Quốc Huy', '0913 223 344', 'https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?auto=format&fit=crop&w=300&q=80', 'host', 'ACTIVE', 'Kinh doanh homestay với phương châm mang lại sự thoải mái tối đa với mức chi phí hợp lý nhất cho mọi chuyến đi.', '2021-06-01T08:00:00Z'),
('user-host-11', 'thanhtruc.phan@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Phan Thanh Trúc', '0935 334 455', 'https://images.unsplash.com/photo-1508214751196-bcfd4ca60f91?auto=format&fit=crop&w=300&q=80', 'host', 'ACTIVE', 'Không gian sống hiện đại, bếp đầy đủ dụng cụ và wifi tốc độ cao cực kỳ thích hợp cho các bạn làm việc từ xa.', '2021-06-01T08:00:00Z'),
('user-host-12', 'minhkhang.do@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Đỗ Minh Khang', '0946 445 566', 'https://images.unsplash.com/photo-1522075469751-3a6694fb2f61?auto=format&fit=crop&w=300&q=80', 'host', 'ACTIVE', 'Nhiệt tình, chu đáo và luôn sẵn sàng hỗ trợ khách hàng bất kỳ lúc nào để chuyến đi của bạn thêm trọn vẹn và đáng nhớ.', '2021-06-01T08:00:00Z'),
('user-host-13', 'dieulinh.trinh@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Trịnh Diệu Linh', '0968 556 677', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=300&q=80', 'host', 'ACTIVE', 'Thiết kế nội thất vintage kết hợp hiện đại. Mỗi góc nhỏ đều mang lại cảm giác bình yên sau một ngày dài khám phá.', '2021-06-01T08:00:00Z'),
('user-host-14', 'tronghieu.nguyen@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Nguyễn Trọng Hiếu', '0919 667 788', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=300&q=80', 'host', 'ACTIVE', 'Host tại các khu đô thị hiện đại Vinhomes Smart City và Vinhomes Central Park. Tiện ích hồ bơi, công viên đỉnh cao.', '2021-06-01T08:00:00Z'),
('user-host-15', 'quynhanh.chu@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Chu Quỳnh Anh', '0938 778 899', 'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=300&q=80', 'host', 'ACTIVE', 'Căn hộ ngắm trọn hoàng hôn Hồ Tây thơ mộng, không gian tĩnh lặng thích hợp cho kỳ nghỉ tái tạo năng lượng.', '2021-06-01T08:00:00Z'),
('user-host-16', 'giahung.ly@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Lý Gia Hưng', '0949 889 900', 'https://images.unsplash.com/photo-1492562080023-ab3db95bfbce?auto=format&fit=crop&w=300&q=80', 'host', 'ACTIVE', 'Tâm huyết với từng trải nghiệm của khách. Đảm bảo phòng ốc thơm tho, sạch sẽ chuẩn khách sạn 4 sao.', '2021-06-01T08:00:00Z'),
('user-host-17', 'camtu.vo@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Võ Cẩm Tú', '0978 990 011', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=300&q=80', 'host', 'ACTIVE', 'Yêu nghệ thuật gốm và tranh ảnh. Không gian căn hộ ấm cúng, thư thái với trà ngon bản địa miễn phí chào mừng.', '2021-06-01T08:00:00Z'),
('user-host-18', 'minhnhat.ta@roomfinder.vn', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Tạ Minh Nhật', '0908 001 122', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=300&q=80', 'host', 'ACTIVE', 'Host thân thiện tại trung tâm Đà Nẵng, cách cầu Rồng chỉ vài phút đi bộ. Sẵn sàng hỗ trợ thuê xe máy và tour tham quan giá tốt.', '2021-06-01T08:00:00Z'),
('user-guest-01', 'phuonglinh.le@gmail.com', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Lê Phương Linh', '0901 234 567', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=256&q=80', 'traveler', 'ACTIVE', 'Khách du lịch trải nghiệm từ Lê Phương Linh.', '2024-02-01T09:00:00Z'),
('user-guest-02', 'hoangquan.do@gmail.com', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Đỗ Hoàng Quân', '0932 456 789', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=256&q=80', 'traveler', 'ACTIVE', 'Khách du lịch trải nghiệm từ Đỗ Hoàng Quân.', '2024-02-01T09:00:00Z'),
('user-guest-03', 'bichngoc.pham@gmail.com', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Phạm Bích Ngọc', '0918 765 432', 'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=256&q=80', 'traveler', 'ACTIVE', 'Khách du lịch trải nghiệm từ Phạm Bích Ngọc.', '2024-02-01T09:00:00Z'),
('user-guest-04', 'minhthang.hoang@gmail.com', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Hoàng Minh Thắng', '0944 332 211', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=256&q=80', 'traveler', 'ACTIVE', 'Khách du lịch trải nghiệm từ Hoàng Minh Thắng.', '2024-02-01T09:00:00Z'),
('user-guest-05', 'thaomy.nguyen@gmail.com', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Nguyễn Thảo My', '0966 554 433', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=256&q=80', 'traveler', 'ACTIVE', 'Khách du lịch trải nghiệm từ Nguyễn Thảo My.', '2024-02-01T09:00:00Z'),
('user-guest-06', 'dinhtrong.tran@gmail.com', '$2a$10$wT8KkC8lQG9WzQhE4JmVOu5H0m1E8H1z3q1vO5n8G1k3q1vO5n8G1', 'Trần Đình Trọng', '0988 776 655', 'https://images.unsplash.com/photo-1492562080023-ab3db95bfbce?auto=format&fit=crop&w=256&q=80', 'traveler', 'ACTIVE', 'Khách du lịch trải nghiệm từ Trần Đình Trọng.', '2024-02-01T09:00:00Z')
